Given a 1-based indexed integer array arr[] that is sorted in non-decreasing order, along with an integer target. find two elements in the array such that their sum is equal to target. If such a pair exists, return the indices of the two elements in increasing order. If no such pair exists, return [-1, -1].Examples:Input: arr[] = [2, 7, 11, 15], target = 9Output: 1 2Explanation: Since the array is 1-indexed, arr[1] + arr[2] = 2 + 7 =  9Input: arr[] = [1, 3, 4, 6, 8, 11] target = 10Output: 3 4Explanation: Since the array is 1-indexed, arr[3] + arr[5] = 4 + 6 = 10Try It YourselfTable of Content[Naive Approach] Try all Pairs - O(n^2) Time and O(1) Space[Expected Approach] Using Two Pointers - O(n) Time and O(1) Space[Naive Approach] Try all Pairs - O(n^2) Time and O(1) SpaceThe idea is to check every possible pair of elements using two nested loops. If any pair adds up to the target, we return their 1-based indices immediately.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> twoSum(vector<int> &arr, int target){
    int n = arr.size();
    // finding all possible pairs
    for(int i = 0; i < n; i++){
        for(int j = i + 1; j < n; j++){
            int sum = arr[i] + arr[j];
            if(sum == target){
                return {i+1, j+1};
            }
        }
    }
    // no pair sum with given target
    return {-1, -1};
}

int main() {
    vector<int> arr = { 2, 7, 11, 15 };
    int target = 9;
    vector<int> result = twoSum(arr, target);
    for (int num : result) {
        cout << num << " ";
    }
    cout << endl;
    return 0;
}


